text:
Class component required — hooks can't catch render errors.

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ── Types ──────────────────────────────────────────────────────────────────

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

// ── Component ──────────────────────────────────────────────────────────────

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Swap for Sentry/Datadog/etc in prod
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
      timestamp: new Date().toISOString(),
    });

    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    // Custom fallback wins
    if (fallback) return fallback(error, this.reset);

    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

// ── Default fallback UI ────────────────────────────────────────────────────

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title:   { margin: "0 0 .5rem", color: "#dc2626" },
  message: { background: "#fee2e2", padding: ".75rem", borderRadius: "4px",
             fontSize: ".85rem", overflowX: "auto" as const },
  button:  { marginTop: "1rem", padding: ".5rem 1.25rem", background: "#dc2626",
             color: "#fff", border: "none", borderRadius: "6px", cursor: "pointer" },
} satisfies Record<string, React.CSSProperties>;
```

**Usage:**

```tsx
// 1 — Default fallback
<ErrorBoundary>
  <RiskyComponent />
</ErrorBoundary>

// 2 — Custom fallback
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
>
  <RiskyComponent />
</ErrorBoundary>

// 3 — Custom logger (Sentry, etc.)
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <RiskyComponent />
</ErrorBoundary>
```

**Key decisions:**

| Choice | Why |
|--------|-----|
| Class component | Only way to use `getDerivedStateFromError` + `componentDidCatch` |
| `reset = () => setState` | Arrow fn = stable ref, safe for prop passing |
| `role="alert"` | Screen readers announce error immediately |
| `satisfies` on styles | Type-checks values, preserves literal types |

**What retry does:** clears error state → re-renders children. If root cause not fixed, error boundary catches again. Pair with key prop to force fresh mount:

```tsx
<ErrorBoundary key={retryCount}>   // increment to remount children
```
